import Foundation
import XCTest
@testable import MorseJoggerCore

/// Live reference vectors generated by tools/mrce-oracle/generate.py, never by Swift.
/// Opt in with MRCE_ORACLE_FIXTURES; the ordinary portable suite needs no Pascal compiler.
final class CompiledPascalCallerTests: XCTestCase {
    private struct Document: Decodable {
        let upstream: String
        let sourceSHA256: String
        let cases: [Vector]
    }
    private struct Vector: Decodable {
        let input: Input
        let expected: Expected
    }
    private struct Input: Decodable {
        let action: String
        let state: OperatorState
        let mode: String
        let patience: Int
        let draw: Double
        var contest: ContestID?
        var lids: Bool?
        var style: Double?
        var counter: Int?
        var silence: Int?
        var stays: Bool?
        var message: String?
        var match: Int?
        var active: Bool?
        var corrected: Bool?
        var incomplete: Int?
        var sessionMode: SessionMode { mode == "hst" ? .hstCompetition : mode == "single" ? .single : .pileup }
    }
    private struct Expected: Decodable {
        let state: OperatorState
        let patience: Int
        let silence: Int
        let incomplete: Int
        let counter: Int
        let corrected: Bool
        let reply: String
        let draws: Int
    }

    private func vectors(_ action: String) throws -> [Vector] {
        guard let path = ProcessInfo.processInfo.environment["MRCE_ORACLE_FIXTURES"] else {
            throw XCTSkip("Run tools/mrce-oracle/generate.py and set MRCE_ORACLE_FIXTURES")
        }
        let document = try JSONDecoder().decode(Document.self, from: Data(contentsOf: URL(fileURLWithPath: path)))
        XCTAssertEqual(document.upstream, "304e51aece5a17f4cba548527816a385a8f6f814")
        XCTAssertEqual(document.sourceSHA256, "65a0eb08c153ec6375d71c82ff04c775a8e49ec3c0afbce626c8c2d39f263bc1")
        let values = document.cases.filter { $0.input.action == action }
        XCTAssertFalse(values.isEmpty)
        return values
    }

    private func station(_ input: Input) -> Station {
        var st = Station(call: "K1ABC", exchange: "599 001", wpm: 25, tone: 600, volume: 1, shift: 0)
        st.opState = input.state
        st.patience = input.patience
        st.replyStyle = input.style ?? 0.5
        st.sendNrQuestionCount = input.counter ?? 0
        st.silentTimeouts = input.silence ?? 0
        st.correctedCallAndExchSent = input.corrected ?? false
        st.incomplete = input.incomplete ?? 0
        st.sentCall = st.call
        return st
    }

    private func settings(_ input: Input) -> ContestSettings {
        var settings = ContestSettings()
        settings.mode = input.sessionMode
        settings.contest = input.contest ?? .wpx
        settings.effects.lids = input.lids ?? false
        settings.callerStays = input.stays ?? false
        settings.callerQrs = false
        return settings
    }

    private func compare<T: Equatable>(_ actual: T, _ expected: T, _ input: Input,
                                       file: StaticString = #filePath, line: UInt = #line) throws {
        guard actual != expected else { return }
        let message = "Compiled MRCE mismatch: \(input); got \(actual), expected \(expected)"
        XCTFail(message, file: file, line: line)
        throw NSError(domain: "MRCEOracle", code: 1, userInfo: [NSLocalizedDescriptionKey: message])
    }

    func testCompiledPascalReplyPolicy() throws {
        let rendered = ["msgNone": "", "msgMyCall": "K1ABC", "msgMyCall2": "K1ABC K1ABC",
                        "msgNrQm": "NR?", "msgAgn": "AGN", "msgNR": "599 001",
                        "msgR_NR": "R 599 001", "msgR_NR2": "R 599 001 599 001",
                        "msgDeMyCall1": "DE K1ABC", "msgDeMyCall2": "DE K1ABC K1ABC",
                        "msgDeMyCallNr1": "DE K1ABC 599 001", "msgDeMyCallNr2": "DE K1ABC K1ABC 599 001",
                        "msgMyCallNr1": "K1ABC 599 001", "msgMyCallNr2": "K1ABC K1ABC 599 001"]
        for vector in try vectors("reply") {
            let input = vector.input, expected = vector.expected
            var st = station(input), draws = 0
            let reply = ContestSimulator.OperatorReplyPolicy.reply(
                &st, cause: .timeout, mode: input.sessionMode, contest: input.contest ?? .wpx,
                lids: input.lids ?? false, nextRandom: { draws += 1; return input.draw })
            let expectedReply = try XCTUnwrap(rendered[expected.reply])
            try compare(reply, expectedReply, input)
            try compare(st.sendNrQuestionCount, expected.counter, input)
            try compare(st.correctedCallAndExchSent, expected.corrected, input)
            try compare(draws, expected.draws, input)
        }
    }

    func testCompiledPascalSilentPatience() throws {
        for vector in try vectors("patience") {
            let input = vector.input, expected = vector.expected
            var st = station(input)
            ContestSimulator(settings: settings(input)).decrementPatience(&st, silent: true)
            try compare(st.opState, expected.state, input)
            try compare(st.patience, expected.patience, input)
            try compare(st.silentTimeouts, expected.silence, input)
        }
    }

    func testCompiledPascalMessageTransitions() throws {
        for vector in try vectors("transition") {
            let input = vector.input, expected = vector.expected
            let simulator = ContestSimulator(settings: settings(input))
            let message = try XCTUnwrap(OperatorInput(rawValue: input.message ?? ""))
            let st = simulator.fixtureOperatorTransition(station(input), input: message,
                                                        confidence: input.match ?? 0, active: input.active ?? true)
            try compare(st.opState, expected.state, input)
            try compare(st.incomplete, expected.incomplete, input)
            try compare(st.sendNrQuestionCount, expected.counter, input)
            try compare(st.correctedCallAndExchSent, expected.corrected, input)
            // Native reset scheduling uses a different RNG stream/order. Only compare
            // deterministic patience values, not a newly randomized NeedQso reset.
            if expected.state != .needQso {
                // Explicit inert difference: native callers are removed on failure;
                // Pascal decrements once after B4 has already marked them Failed.
                let terminalB4 = input.message == "b4" && expected.state == .failed
                try compare(st.patience, expected.patience + (terminalB4 ? 1 : 0), input)
            }
        }
    }
}
